INSERT INTO entity_citations (citation_id,entity_id,source_id,work_title,locus,quote,translator,translation_year,source_url,original_text_url,evidence_grade,evidence_note,needs_review,review_reason,verified_on,verify_method,display_order) VALUES
('CIT_ADIKIA_PAUSAN','ENT_ADIKIA','SRC_PAUSANIAS_DESCRIPTION','Pausanias, Description of Greece','Pausanias, Description of Greece','And there is a comely woman dragging along an ugly one, with one hand holding her fast, and with the other beating her with a rod, this is Justice punishing Injustice. And there are two women pounding with pestles into mortars, apparently compounding drugs, but there is no inscription in reference to them.','A. R. Shilleto',1886,'https://www.gutenberg.org/ebooks/68946','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0159','primary-verbatim',NULL,true,'English translation (A. R. Shilleto, Bohn ed., Gutenberg #68946/#68680) located by name; verify book.chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_CAERUS_PAUSAN','ENT_CAERUS','SRC_PAUSANIAS_DESCRIPTION','Pausanias, Description of Greece','Pausanias, Description of Greece','And there are two altars very near the entrance to the race-course, one they say of Hermes the Athlete, and the other of Opportunity. Ion the Chian has I know written an Hymn to Opportunity, in which he traces his genealogy, and makes him the youngest son of Zeus. And near the treasure of the Sicyonians is an altar of Hercules, either one of the Curetes, or the son of Alcmena, for both traditions are current.','A. R. Shilleto',1886,'https://www.gutenberg.org/ebooks/68946','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0159','primary-verbatim',NULL,true,'English translation (A. R. Shilleto, Bohn ed., Gutenberg #68946/#68680) located by name; verify book.chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_DACTYLS_PAUSAN','ENT_DACTYLS','SRC_PAUSANIAS_DESCRIPTION','Pausanias, Description of Greece','Pausanias, Description of Greece','den age: and that, when Zeus was born, Rhea entrusted the charge of the boy to the Idaean Dactyli, who were otherwise called the Curetes: who afterwards came to Elis from Ida in Crete, and their names were Hercules, and Epimedes, and Paeonaeus, and Iasius, and Idas.','A. R. Shilleto',1886,'https://www.gutenberg.org/ebooks/68946','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0159','primary-verbatim',NULL,true,'English translation (A. R. Shilleto, Bohn ed., Gutenberg #68946/#68680) located by name; verify book.chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_EPHYRA_PAUSAN','ENT_EPHYRA','SRC_PAUSANIAS_DESCRIPTION','Pausanias, Description of Greece','Pausanias, Description of Greece','But Eumœlus'' account is that the Sun gave Asopia to Aloeus, and Ephyraea to Aeetes: and Aeetes went to Colchis, and left the kingdom to Bunus the son of Hermes and Alcidamea, and after Bunus'' death, Epopeus reigned over the Ephyraeans.','A. R. Shilleto',1886,'https://www.gutenberg.org/ebooks/68946','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0159','primary-verbatim',NULL,true,'English translation (A. R. Shilleto, Bohn ed., Gutenberg #68946/#68680) located by name; verify book.chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_HADES_KLYMENOS_PAUSAN','ENT_HADES_KLYMENOS','SRC_PAUSANIAS_DESCRIPTION','Pausanias, Description of Greece','Pausanias, Description of Greece','And I fancy that Homer, having seen these, ventured to introduce them in his account of the rivers of Hades, and to borrow his names from these rivers in Thesprotia. However that may be, Theseus being detained there, the sons of Tyndarus led an expedition to Aphidna, and captured it, and restored Menestheus to the kingdom.','A. R. Shilleto',1886,'https://www.gutenberg.org/ebooks/68946','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0159','primary-verbatim',NULL,true,'English translation (A. R. Shilleto, Bohn ed., Gutenberg #68946/#68680) located by name; verify book.chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_HYGIEIA_PAUSAN','ENT_HYGIEIA','SRC_PAUSANIAS_DESCRIPTION','Pausanias, Description of Greece','Pausanias, Description of Greece','And next to Diitrephes, (I shall not mention the more obscure images), are some statues of goddesses, as Hygiea, (_Health_), who they say was the daughter of Aesculapius, and Athene by the same name of Hygiea. And there is a small stone such as a little man can sit on, on which they say Silenus rested, when Dionysus came to the land. Silenus is the name they give to all old Satyrs.','A. R. Shilleto',1886,'https://www.gutenberg.org/ebooks/68946','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0159','primary-verbatim',NULL,true,'English translation (A. R. Shilleto, Bohn ed., Gutenberg #68946/#68680) located by name; verify book.chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_IPHIGENIA_PAUSAN','ENT_IPHIGENIA','SRC_PAUSANIAS_DESCRIPTION','Pausanias, Description of Greece','Pausanias, Description of Greece','And not far from Marathon is Brauron, where they say Iphigenia, the daughter of Agamemnon, landed in her flight from the Tauri, bringing with her the statue of Artemis, and, having left it here, went on to Athens and afterwards to Argos. Here is indeed an ancient statue of Artemis. But those who have the Tauric statue of the goddess in my opinion, I shall show in another part of my work.','A. R. Shilleto',1886,'https://www.gutenberg.org/ebooks/68946','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0159','primary-verbatim',NULL,true,'English translation (A. R. Shilleto, Bohn ed., Gutenberg #68946/#68680) located by name; verify book.chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_KORE_PAUSAN','ENT_KORE','SRC_PAUSANIAS_DESCRIPTION','Pausanias, Description of Greece','Pausanias, Description of Greece','The story goes then that when Demeter came to Argos Pelasgus received her into his house, and that Chrysanthis, knowing of the rape of Proserpine, informed her of it: and afterwards Trochilus the initiating priest fled they say from Argos in consequence of the hatred of Agenor, and came to Attica, and there married a wife from Eleusis, and had children by her, Eubules and Triptolemus. This is the account of the Argives.','A. R. Shilleto',1886,'https://www.gutenberg.org/ebooks/68946','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0159','primary-verbatim',NULL,true,'English translation (A. R. Shilleto, Bohn ed., Gutenberg #68946/#68680) located by name; verify book.chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_PRAXIS_PAUSAN','ENT_PRAXIS','SRC_PAUSANIAS_DESCRIPTION','Pausanias, Description of Greece','Pausanias, Description of Greece','And next to the temple of Dionysus is the shrine of Aphrodite, and a statue of the goddess in ivory, under the title Praxis (_Action_). This is the oldest statue in the shrine. And _Persuasion_ and another goddess whom they call _Consolation_ are by Praxiteles: and by Scopas _Love_ and _Desire_ and _Yearning_, each statue expressing the particular shade of meaning marked by the words.','A. R. Shilleto',1886,'https://www.gutenberg.org/ebooks/68946','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0159','primary-verbatim',NULL,true,'English translation (A. R. Shilleto, Bohn ed., Gutenberg #68946/#68680) located by name; verify book.chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1)
